"""DAFT-style output directories, scoped to an explicit output filename."""
from pathlib import Path
import shutil


def folders(output):
    output = Path(output).resolve()
    name = output.stem
    parent = output.parent
    return {kind: parent / f"reconcILS_{kind}_{name}" for kind in ("results", "extras", "log")}


def organize_single(output, alias_output, validator):
    """Move only known files generated by this run; never sweep unrelated files."""
    output = Path(output).resolve()
    destinations = folders(output)
    files = {
        "results": [output],
        "extras": [Path(alias_output), getattr(validator, "taxon_report_path", None),
                   getattr(validator, "validation_report_path", None)],
        "log": [output.with_name(output.stem + "_log.csv"), getattr(validator, "log_path", None)],
    }
    moved = {}
    for kind, paths in files.items():
        for value in paths:
            if not value:
                continue
            source = Path(value).resolve()
            if not source.is_file():
                continue
            destination = destinations[kind] / source.name
            if source == destination:
                moved[str(source)] = str(destination)
                continue
            destinations[kind].mkdir(parents=True, exist_ok=True)
            if destination.exists():
                raise FileExistsError(f"Refusing to overwrite existing output: {destination}")
            shutil.move(str(source), str(destination))
            moved[str(source)] = str(destination)
    return destinations, moved
